import { cookies, headers } from 'next/headers';

export default async function ThemePreference() {
  const cookieStore = await cookies();
  const theme = cookieStore.get('theme')?.value || 'light';

  const headersList = await headers();
  const acceptLanguage = headersList.get('accept-language') || 'No language preference found';

  return (
    <div style={{ padding: '20px', border: '1px solid #ccc', borderRadius: '8px', maxWidth: '400px' }}>
      <h2>Theme Preference</h2>
      <p>Current Theme: <strong>{theme}</strong></p>

      <h3>Language Preference</h3>
      <p>Accept-Language: <code>{acceptLanguage}</code></p>
    </div>
  );
}

