import { cookies, headers } from 'next/headers';

export default async function ThemePreference() {
  const cookieStore = await cookies();
  const themeCookie = cookieStore.get('theme');
  const theme = themeCookie?.value || 'light';

  const headersList = await headers();
  const acceptLanguage = headersList.get('accept-language');

  return (
    <div style={{ 
      padding: '20px', 
      border: '1px solid #e5e7eb', 
      borderRadius: '8px', 
      backgroundColor: '#f9fafb',
      fontFamily: 'system-ui, sans-serif',
      maxWidth: '500px',
      margin: '20px 0'
    }}>
      <h2 style={{ marginTop: 0, marginBottom: '16px', color: '#111827' }}>
        User Preferences
      </h2>

      <div style={{ marginBottom: '16px' }}>
        <h3 style={{ margin: '0 0 8px 0', fontSize: '1rem', color: '#374151' }}>
          Theme
        </h3>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <span style={{ 
            fontFamily: 'monospace', 
            backgroundColor: '#e5e7eb', 
            padding: '2px 6px', 
            borderRadius: '4px' 
          }}>
            {theme}
          </span>
          {!themeCookie && (
            <span style={{ fontSize: '0.875rem', color: '#6b7280' }}>
              (Default: no cookie found)
            </span>
          )}
        </div>
      </div>

      <div>
        <h3 style={{ margin: '0 0 8px 0', fontSize: '1rem', color: '#374151' }}>
          Language (Accept-Language)
        </h3>
        <span style={{ 
          fontFamily: 'monospace', 
          backgroundColor: '#e5e7eb', 
          padding: '2px 6px', 
          borderRadius: '4px',
          wordBreak: 'break-all'
        }}>
          {acceptLanguage || 'Not specified'}
        </span>
      </div>
    </div>
  );
}

